<?php require __DIR__.'/../includes/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'pending';if($pdo&&$id&&in_array($status,['pending','approved','spam','deleted'],true))$pdo->prepare('UPDATE comments SET status=? WHERE id=?')->execute([$status,$id]);header('Location: comments.php');exit;}$rows=$pdo?$pdo->query('SELECT c.*,a.title article_title FROM comments c JOIN articles a ON a.id=c.article_id ORDER BY c.created_at DESC')->fetchAll():[];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comments</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Comment Moderation</h1><p><a href="dashboard.php">Dashboard</a></p><?php foreach($rows as $r):?><article class="card" style="margin-bottom:14px"><p><strong><?=e($r['article_title'])?></strong> · <?=e($r['status'])?></p><p><?=nl2br(e($r['body']))?></p><p class="muted"><?=e($r['name'])?> (<?=e($r['email'])?>) · <?=e($r['created_at'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['pending','approved','spam','deleted'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select> <button>Update status</button></form></article><?php endforeach;if(!$rows):?><p class="muted">No comments found.</p><?php endif;?></main></body></html>
